  1	package com.pousadamarealta;
  2	
  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.fasterxml.jackson.databind.SerializationFeature;
  5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  6	import com.pousadamarealta.document.DocumentService;
  7	import com.pousadamarealta.repository.MessageRepository;
  8	import com.pousadamarealta.repository.ReservationRepository;
  9	import com.pousadamarealta.repository.RoomRepository;
 10	import com.pousadamarealta.service.ReportService;
 11	import com.pousadamarealta.service.ReservationService;
 12	import com.pousadamarealta.web.ApiController;
 13	import com.zaxxer.hikari.HikariConfig;
 14	import com.zaxxer.hikari.HikariDataSource;
 15	import io.javalin.Javalin;
 16	import io.javalin.json.JavalinJackson;
 17	
 18	public class App {
 19	    public static void main(String[] args) {
 20	        HikariDataSource dataSource = createDataSource();
 21	
 22	        RoomRepository roomRepository = new RoomRepository(dataSource);
 23	        ReservationRepository reservationRepository = new ReservationRepository(dataSource);
 24	        MessageRepository messageRepository = new MessageRepository(dataSource);
 25	
 26	        roomRepository.initialize();
 27	        reservationRepository.initialize();
 28	        messageRepository.initialize();
 29	
 30	        DocumentService documentService = new DocumentService();
 31	        ReservationService reservationService = new ReservationService(
 32	            reservationRepository, roomRepository, messageRepository, documentService);
 33	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 34	
 35	        ApiController apiController = new ApiController(
 36	            roomRepository, messageRepository, reservationService, reportService);
 37	
 38	        int port = getPort();
 39	
 40	        ObjectMapper objectMapper = new ObjectMapper()
 41	            .registerModule(new JavaTimeModule())
 42	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 43	
 44	        Javalin app = Javalin.create(config -> {
 45	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 46	        }).start(port);
 47	
 48	        apiController.registerRoutes(app);
 49	
 50	        System.out.println("Server started on port " + port);
 51	    }
 52	
 53	    private static HikariDataSource createDataSource() {
 54	        String url = System.getenv("DB_URL");
 55	        String user = System.getenv("DB_USER");
 56	        String password = System.getenv("DB_PASSWORD");
 57	
 58	        if (url == null) {
 59	            throw new IllegalStateException("DB_URL environment variable is not set");
 60	        }
 61	        if (user == null) {
 62	            throw new IllegalStateException("DB_USER environment variable is not set");
 63	        }
 64	        if (password == null) {
 65	            throw new IllegalStateException("DB_PASSWORD environment variable is not set");
 66	        }
 67	
 68	        HikariConfig config = new HikariConfig();
 69	        config.setJdbcUrl(url);
 70	        config.setUsername(user);
 71	        config.setPassword(password);
 72	        config.setMaximumPoolSize(10);
 73	
 74	        return new HikariDataSource(config);
 75	    }
 76	
 77	    private static int getPort() {
 78	        String portEnv = System.getenv("PORT");
 79	        if (portEnv != null) {
 80	            try {
 81	                return Integer.parseInt(portEnv);
 82	            } catch (NumberFormatException e) {
 83	                System.err.println("Invalid PORT value, using default 7070");
 84	            }
 85	        }
 86	        return 7070;
 87	    }
 88	}
 89	package com.pousadamarealta.web;
 90	
 91	import com.fasterxml.jackson.databind.JsonNode;
 92	import com.pousadamarealta.document.Document;
 93	import com.pousadamarealta.domain.*;
 94	import com.pousadamarealta.repository.MessageRepository;
 95	import com.pousadamarealta.repository.RoomRepository;
 96	import com.pousadamarealta.service.ReportService;
 97	import com.pousadamarealta.service.ReservationService;
 98	import io.javalin.Javalin;
 99	import io.javalin.http.Context;
100	import java.math.BigDecimal;
101	import java.time.LocalDate;
102	import java.time.YearMonth;
103	import java.time.format.DateTimeFormatter;
104	import java.time.format.DateTimeParseException;
105	import java.util.List;
106	import java.util.Map;
107	
108	public final class ApiController {
109	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
110	    private static final DateTimeFormatter MONTH_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM");
111	
112	    private final RoomRepository roomRepository;
113	    private final MessageRepository messageRepository;
114	    private final ReservationService reservationService;
115	    private final ReportService reportService;
116	
117	    public ApiController(RoomRepository roomRepository, MessageRepository messageRepository,
118	                        ReservationService reservationService, ReportService reportService) {
119	        this.roomRepository = roomRepository;
120	        this.messageRepository = messageRepository;
121	        this.reservationService = reservationService;
122	        this.reportService = reportService;
123	    }
124	
125	    public void registerRoutes(Javalin app) {
126	        app.get("/rooms", this::getRooms);
127	        app.post("/reservations", this::createReservation);
128	        app.get("/reservations/{id}", this::getReservation);
129	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
130	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
131	        app.post("/reservations/{id}/check-in", this::checkIn);
132	        app.post("/reservations/{id}/check-out", this::checkOut);
133	        app.get("/reservations/{id}/document", this::getDocument);
134	        app.get("/messages", this::getMessages);
135	        app.get("/reports/occupancy", this::getOccupancyReport);
136	        app.get("/reports/revenue", this::getRevenueReport);
137	
138	        app.exception(ReservationService.RoomNotFoundException.class, (e, ctx) -> {
139	            ctx.status(404).json(Map.of("error", "ROOM_NOT_FOUND", "message", "Room not found"));
140	        });
141	        app.exception(ReservationService.ReservationNotFoundException.class, (e, ctx) -> {
142	            ctx.status(404).json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
143	        });
144	        app.exception(ReservationService.RoomUnavailableException.class, (e, ctx) -> {
145	            ctx.status(409).json(Map.of("error", "ROOM_UNAVAILABLE", "message", "Room is not available for the selected dates"));
146	        });
147	        app.exception(ReservationService.CapacityExceededException.class, (e, ctx) -> {
148	            ctx.status(422).json(Map.of("error", "CAPACITY_EXCEEDED", "message", "Number of guests exceeds room capacity"));
149	        });
150	        app.exception(ReservationService.OperationNotAllowedException.class, (e, ctx) -> {
151	            ctx.status(409).json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", "Operation not allowed in current reservation state"));
152	        });
153	        app.exception(ReservationService.InvalidRequestException.class, (e, ctx) -> {
154	            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
155	        });
156	        app.exception(InvalidRequestException.class, (e, ctx) -> {
157	            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
158	        });
159	    }
160	
161	    private void getRooms(Context ctx) {
162	        List<Room> rooms = roomRepository.findAll();
163	        ctx.json(rooms.stream()
164	            .map(r -> Map.of(
165	                "number", r.number(),
166	                "type", r.type(),
167	                "capacity", r.capacity(),
168	                "nightlyRate", r.nightlyRate()
169	            ))
170	            .toList());
171	    }
172	
173	    private void createReservation(Context ctx) {
174	        try {
175	            JsonNode json = ctx.bodyAsClass(JsonNode.class);
176	
177	            int roomNumber = getRequiredInt(json, "roomNumber");
178	            String guestName = getRequiredString(json, "guestName");
179	            String guestEmail = getRequiredString(json, "guestEmail");
180	            LocalDate checkIn = parseDate(getRequiredString(json, "checkIn"));
181	            LocalDate checkOut = parseDate(getRequiredString(json, "checkOut"));
182	            int guests = getRequiredInt(json, "guests");
183	            RatePlan ratePlan = RatePlan.valueOf(getRequiredString(json, "ratePlan"));
184	
185	            GuestIdentification guestId = parseGuestIdentification(json);
186	
187	            Reservation reservation = reservationService.createReservation(
188	                roomNumber, guestName, guestEmail, guestId, checkIn, checkOut, guests, ratePlan);
189	
190	            ctx.status(201).json(toReservationResponse(reservation));
191	        } catch (IllegalArgumentException e) {
192	            throw new InvalidRequestException(e.getMessage());
193	        }
194	    }
195	
196	    private void getReservation(Context ctx) {
197	        long id = ctx.pathParamAsClass("id", Long.class).get();
198	        Reservation reservation = reservationService.getReservation(id);
199	        ctx.json(toReservationResponse(reservation));
200	    }
201	
202	    private void confirmReservation(Context ctx) {
203	        long id = ctx.pathParamAsClass("id", Long.class).get();
204	        Reservation reservation = reservationService.confirmReservation(id);
205	        ctx.json(toReservationResponse(reservation));
206	    }
207	
208	    private void cancelReservation(Context ctx) {
209	        long id = ctx.pathParamAsClass("id", Long.class).get();
210	        Reservation reservation = reservationService.cancelReservation(id);
211	        ctx.json(toReservationResponse(reservation));
212	    }
213	
214	    private void checkIn(Context ctx) {
215	        long id = ctx.pathParamAsClass("id", Long.class).get();
216	        Reservation reservation = reservationService.checkInReservation(id);
217	        ctx.json(toReservationResponse(reservation));
218	    }
219	
220	    private void checkOut(Context ctx) {
221	        long id = ctx.pathParamAsClass("id", Long.class).get();
222	        Document document = reservationService.checkOutReservation(id);
223	        ctx.json(toDocumentResponse(document));
224	    }
225	
226	    private void getDocument(Context ctx) {
227	        long id = ctx.pathParamAsClass("id", Long.class).get();
228	        Document document = reservationService.getDocument(id);
229	        ctx.json(toDocumentResponse(document));
230	    }
231	
232	    private void getMessages(Context ctx) {
233	        List<Message> messages = messageRepository.findAll();
234	        ctx.json(messages.stream()
235	            .map(m -> Map.of(
236	                "id", m.id(),
237	                "channel", m.channel(),
238	                "to", m.to(),
239	                "subject", m.subject(),
240	                "body", m.body()
241	            ))
242	            .toList());
243	    }
244	
245	    private void getOccupancyReport(Context ctx) {
246	        String dateParam = ctx.queryParam("date");
247	        if (dateParam == null) {
248	            throw new InvalidRequestException("Missing date parameter");
249	        }
250	
251	        try {
252	            LocalDate date = LocalDate.parse(dateParam, DATE_FORMATTER);
253	            String csv = reportService.generateOccupancyReport(date);
254	            ctx.contentType("text/csv; charset=utf-8").result(csv);
255	        } catch (DateTimeParseException e) {
256	            throw new InvalidRequestException("Invalid date format");
257	        }
258	    }
259	
260	    private void getRevenueReport(Context ctx) {
261	        String monthParam = ctx.queryParam("month");
262	        if (monthParam == null) {
263	            throw new InvalidRequestException("Missing month parameter");
264	        }
265	
266	        try {
267	            YearMonth yearMonth = YearMonth.parse(monthParam, MONTH_FORMATTER);
268	            String csv = reportService.generateRevenueReport(yearMonth.getYear(), yearMonth.getMonthValue());
269	            ctx.contentType("text/csv; charset=utf-8").result(csv);
270	        } catch (DateTimeParseException e) {
271	            throw new InvalidRequestException("Invalid month format");
272	        }
273	    }
274	
275	    private GuestIdentification parseGuestIdentification(JsonNode json) {
276	        boolean hasCpf = json.has("guestCpf") && !json.get("guestCpf").isNull();
277	        boolean hasPassport = json.has("guestPassport") && !json.get("guestPassport").isNull();
278	        boolean hasCnpj = json.has("companyCnpj") && !json.get("companyCnpj").isNull();
279	
280	        int count = (hasCpf ? 1 : 0) + (hasPassport ? 1 : 0) + (hasCnpj ? 1 : 0);
281	        if (count != 1) {
282	            throw new InvalidRequestException("Exactly one of guestCpf, guestPassport, or companyCnpj must be provided");
283	        }
284	
285	        if (hasCpf) {
286	            return new GuestIdentification.IndividualGuest(json.get("guestCpf").asText());
287	        } else if (hasPassport) {
288	            String passport = json.get("guestPassport").asText();
289	            String country = getRequiredString(json, "guestCountry");
290	            return new GuestIdentification.ForeignGuest(passport, country);
291	        } else {
292	            String cnpj = json.get("companyCnpj").asText();
293	            String companyName = getRequiredString(json, "companyName");
294	            return new GuestIdentification.CorporateGuest(cnpj, companyName);
295	        }
296	    }
297	
298	    private Map<String, Object> toReservationResponse(Reservation r) {
299	        Map<String, Object> map = new java.util.LinkedHashMap<>();
300	        map.put("id", r.id());
301	        map.put("roomNumber", r.roomNumber());
302	        map.put("guestName", r.guestName());
303	        map.put("guestEmail", r.guestEmail());
304	
305	        if (r.guestIdentification() instanceof GuestIdentification.IndividualGuest individual) {
306	            map.put("guestCpf", individual.cpf());
307	            map.put("guestPassport", null);
308	            map.put("guestCountry", null);
309	            map.put("companyCnpj", null);
310	            map.put("companyName", null);
311	        } else if (r.guestIdentification() instanceof GuestIdentification.ForeignGuest foreign) {
312	            map.put("guestCpf", null);
313	            map.put("guestPassport", foreign.passport());
314	            map.put("guestCountry", foreign.country());
315	            map.put("companyCnpj", null);
316	            map.put("companyName", null);
317	        } else if (r.guestIdentification() instanceof GuestIdentification.CorporateGuest corporate) {
318	            map.put("guestCpf", null);
319	            map.put("guestPassport", null);
320	            map.put("guestCountry", null);
321	            map.put("companyCnpj", corporate.cnpj());
322	            map.put("companyName", corporate.companyName());
323	        }
324	
325	        map.put("checkIn", r.checkIn());
326	        map.put("checkOut", r.checkOut());
327	        map.put("guests", r.guests());
328	        map.put("ratePlan", r.ratePlan());
329	        map.put("nights", r.nights());
330	        map.put("subtotal", r.subtotal());
331	        map.put("discount", r.discount());
332	        map.put("total", r.total());
333	        map.put("status", r.status());
334	        map.put("amountPaid", r.amountPaid());
335	        map.put("refund", r.refund());
336	
337	        return map;
338	    }
339	
340	    private Map<String, Object> toDocumentResponse(Document d) {
341	        Map<String, Object> map = new java.util.LinkedHashMap<>();
342	        map.put("title", d.title());
343	        map.put("reservationId", d.reservationId());
344	        map.put("guestName", d.guestName());
345	        map.put("guestCpf", d.guestCpf());
346	        map.put("guestPassport", d.guestPassport());
347	        map.put("guestCountry", d.guestCountry());
348	        map.put("companyCnpj", d.companyCnpj());
349	        map.put("companyName", d.companyName());
350	        map.put("roomNumber", d.roomNumber());
351	        map.put("roomType", d.roomType());
352	        map.put("checkIn", d.checkIn());
353	        map.put("checkOut", d.checkOut());
354	        map.put("nights", d.nights());
355	        map.put("subtotal", d.subtotal());
356	        map.put("discount", d.discount());
357	        map.put("total", d.total());
358	        map.put("text", d.text());
359	        return map;
360	    }
361	
362	    private String getRequiredString(JsonNode json, String field) {
363	        if (!json.has(field) || json.get(field).isNull()) {
364	            throw new InvalidRequestException("Missing required field: " + field);
365	        }
366	        return json.get(field).asText();
367	    }
368	
369	    private int getRequiredInt(JsonNode json, String field) {
370	        if (!json.has(field) || json.get(field).isNull()) {
371	            throw new InvalidRequestException("Missing required field: " + field);
372	        }
373	        return json.get(field).asInt();
374	    }
375	
376	    private LocalDate parseDate(String date) {
377	        try {
378	            return LocalDate.parse(date, DATE_FORMATTER);
379	        } catch (DateTimeParseException e) {
380	            throw new InvalidRequestException("Invalid date format: " + date);
381	        }
382	    }
383	
384	    static class InvalidRequestException extends RuntimeException {
385	        InvalidRequestException(String message) {
386	            super(message);
387	        }
388	    }
389	}

