275	    private GuestIdentification parseGuestIdentification(JsonNode json) {
276	        boolean hasCpf = json.has("guestCpf") && !json.get("guestCpf").isNull();
277	        boolean hasPassport = json.has("guestPassport") && !json.get("guestPassport").isNull();
278	        boolean hasCnpj = json.has("companyCnpj") && !json.get("companyCnpj").isNull();
279	
280	        int count = (hasCpf ? 1 : 0) + (hasPassport ? 1 : 0) + (hasCnpj ? 1 : 0);
281	        if (count != 1) {
282	            throw new InvalidRequestException("Exactly one of guestCpf, guestPassport, or companyCnpj must be provided");
283	        }
284	
285	        if (hasCpf) {
286	            return new GuestIdentification.IndividualGuest(json.get("guestCpf").asText());
287	        } else if (hasPassport) {
288	            String passport = json.get("guestPassport").asText();
289	            String country = getRequiredString(json, "guestCountry");
290	            return new GuestIdentification.ForeignGuest(passport, country);
291	        } else {
292	            String cnpj = json.get("companyCnpj").asText();
293	            String companyName = getRequiredString(json, "companyName");
294	            return new GuestIdentification.CorporateGuest(cnpj, companyName);
295	        }
296	    }
