298	    private Map<String, Object> toReservationResponse(Reservation r) {
299	        Map<String, Object> map = new java.util.LinkedHashMap<>();
300	        map.put("id", r.id());
301	        map.put("roomNumber", r.roomNumber());
302	        map.put("guestName", r.guestName());
303	        map.put("guestEmail", r.guestEmail());
304	
305	        if (r.guestIdentification() instanceof GuestIdentification.IndividualGuest individual) {
306	            map.put("guestCpf", individual.cpf());
307	            map.put("guestPassport", null);
308	            map.put("guestCountry", null);
309	            map.put("companyCnpj", null);
310	            map.put("companyName", null);
311	        } else if (r.guestIdentification() instanceof GuestIdentification.ForeignGuest foreign) {
312	            map.put("guestCpf", null);
313	            map.put("guestPassport", foreign.passport());
314	            map.put("guestCountry", foreign.country());
315	            map.put("companyCnpj", null);
316	            map.put("companyName", null);
317	        } else if (r.guestIdentification() instanceof GuestIdentification.CorporateGuest corporate) {
318	            map.put("guestCpf", null);
319	            map.put("guestPassport", null);
320	            map.put("guestCountry", null);
321	            map.put("companyCnpj", corporate.cnpj());
322	            map.put("companyName", corporate.companyName());
323	        }
324	
325	        map.put("checkIn", r.checkIn());
326	        map.put("checkOut", r.checkOut());
327	        map.put("guests", r.guests());
328	        map.put("ratePlan", r.ratePlan());
329	        map.put("nights", r.nights());
330	        map.put("subtotal", r.subtotal());
331	        map.put("discount", r.discount());
332	        map.put("total", r.total());
333	        map.put("status", r.status());
334	        map.put("amountPaid", r.amountPaid());
335	        map.put("refund", r.refund());
336	
337	        return map;
338	    }
