362	    private String getRequiredString(JsonNode json, String field) {
363	        if (!json.has(field) || json.get(field).isNull()) {
364	            throw new InvalidRequestException("Missing required field: " + field);
365	        }
366	        return json.get(field).asText();
367	    }
368	
369	    private int getRequiredInt(JsonNode json, String field) {
370	        if (!json.has(field) || json.get(field).isNull()) {
371	            throw new InvalidRequestException("Missing required field: " + field);
372	        }
373	        return json.get(field).asInt();
374	    }
