 13	public final class ReportService {
 14	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 15	
 16	    private final ReservationRepository reservationRepository;
 17	    private final RoomRepository roomRepository;
 18	
 19	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
 20	        this.reservationRepository = reservationRepository;
 21	        this.roomRepository = roomRepository;
 22	    }
 23	
 24	    public String generateOccupancyReport(LocalDate date) {
 25	        List<Room> allRooms = roomRepository.findAll();
 26	        StringBuilder csv = new StringBuilder();
 27	        csv.append("room,type,reservation,check_in,check_out\n");
 28	
 29	        int occupiedCount = 0;
 30	
 31	        for (Room room : allRooms) {
 32	            List<Reservation> reservations = reservationRepository.findByRoomAndDateRange(
 33	                room.number(), date, date.plusDays(1));
 34	
 35	            Reservation occupying = reservations.stream()
 36	                .filter(r -> r.status() == ReservationStatus.CONFIRMED ||
 37	                           r.status() == ReservationStatus.CHECKED_IN ||
 38	                           r.status() == ReservationStatus.CHECKED_OUT)
 39	                .filter(r -> !r.checkIn().isAfter(date) && r.checkOut().isAfter(date))
 40	                .findFirst()
 41	                .orElse(null);
 42	
 43	            if (occupying != null) {
 44	                csv.append(room.number()).append(",")
 45	                   .append(room.type()).append(",")
 46	                   .append(occupying.id()).append(",")
 47	                   .append(occupying.checkIn().format(DATE_FORMATTER)).append(",")
 48	                   .append(occupying.checkOut().format(DATE_FORMATTER)).append("\n");
 49	                occupiedCount++;
 50	            }
 51	        }
 52	
 53	        csv.append("total,").append(occupiedCount).append("/").append(allRooms.size()).append("\n");
 54	
 55	        return csv.toString();
 56	    }
 57	
 58	    public String generateRevenueReport(int year, int month) {
 59	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(year, month);
 60	
 61	        StringBuilder csv = new StringBuilder();
 62	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 63	
 64	        BigDecimal total = BigDecimal.ZERO;
 65	
 66	        for (Reservation r : reservations) {
 67	            BigDecimal amount = r.amountPaid();
 68	            if (r.refund() != null) {
 69	                amount = amount.subtract(r.refund());
 70	            }
 71	
 72	            if (amount.compareTo(BigDecimal.ZERO) > 0) {
 73	                csv.append(r.id()).append(",")
 74	                   .append(r.roomNumber()).append(",")
 75	                   .append(r.checkIn().format(DATE_FORMATTER)).append(",")
 76	                   .append(r.checkOut().format(DATE_FORMATTER)).append(",")
 77	                   .append(r.status()).append(",")
 78	                   .append(formatAmount(amount)).append("\n");
 79	                total = total.add(amount);
 80	            }
 81	        }
 82	
 83	        csv.append("total,").append(formatAmount(total)).append("\n");
 84	
 85	        return csv.toString();
 86	    }
 87	
 88	    private String formatAmount(BigDecimal amount) {
 89	        return amount.toString();
 90	    }
 91	}
