108	
109	    public ReservationService(ReservationRepository reservationRepository,
110	                             RoomRepository roomRepository,
111	                             MessageRepository messageRepository,
112	                             DocumentService documentService) {
113	        this.reservationRepository = reservationRepository;
114	        this.roomRepository = roomRepository;
115	        this.messageRepository = messageRepository;
116	        this.documentService = documentService;
