119	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
120	                                        GuestIdentification guestIdentification, LocalDate checkIn,
121	                                        LocalDate checkOut, int guests, RatePlan ratePlan) {
122	        Room room = roomRepository.findByNumber(roomNumber)
123	            .orElseThrow(() -> new RoomNotFoundException());
124	
125	        if (guests > room.capacity()) {
126	            throw new CapacityExceededException();
127	        }
128	
129	        if (guests < 1) {
130	            throw new InvalidRequestException("At least one guest is required");
131	        }
132	
133	        if (!checkOut.isAfter(checkIn)) {
134	            throw new InvalidRequestException("Check-out must be after check-in");
135	        }
136	
137	        List<Reservation> conflicts = reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
138	        if (!conflicts.isEmpty()) {
139	            throw new RoomUnavailableException();
140	        }
141	
142	        Reservation reservation = new Reservation(0, roomNumber, guestName, guestEmail,
143	            guestIdentification, checkIn, checkOut, guests, ratePlan, room.nightlyRate());
144	
145	        return reservationRepository.save(reservation);
146	    }
147	
148	    public Reservation getReservation(long id) {
149	        return reservationRepository.findById(id)
150	            .orElseThrow(() -> new ReservationNotFoundException());
151	    }
152	
153	    public Reservation confirmReservation(long id) {
154	        Reservation reservation = getReservation(id);
155	
156	        try {
157	            reservation.confirm();
158	        } catch (IllegalStateException e) {
159	            throw new OperationNotAllowedException();
160	        }
161	
162	        Reservation saved = reservationRepository.save(reservation);
163	        sendConfirmationEmail(saved);
164	        return saved;
165	    }
166	
167	    public Reservation cancelReservation(long id) {
168	        Reservation reservation = getReservation(id);
169	
170	        try {
171	            reservation.cancel();
172	        } catch (IllegalStateException e) {
173	            throw new OperationNotAllowedException();
174	        }
175	
176	        return reservationRepository.save(reservation);
177	    }
178	
179	    public Reservation checkInReservation(long id) {
180	        Reservation reservation = getReservation(id);
181	
182	        try {
183	            reservation.performCheckIn();
184	        } catch (IllegalStateException e) {
185	            throw new OperationNotAllowedException();
186	        }
187	
188	        return reservationRepository.save(reservation);
189	    }
190	
191	    public Document checkOutReservation(long id) {
192	        Reservation reservation = getReservation(id);
193	
194	        try {
195	            reservation.performCheckOut();
196	        } catch (IllegalStateException e) {
197	            throw new OperationNotAllowedException();
198	        }
199	
200	        reservationRepository.save(reservation);
201	        return generateDocument(reservation);
202	    }
203	
204	    public Document getDocument(long id) {
205	        Reservation reservation = getReservation(id);
206	
207	        if (reservation.status() == ReservationStatus.PENDING ||
208	            reservation.status() == ReservationStatus.CANCELLED) {
209	            throw new OperationNotAllowedException();
210	        }
211	
212	        return generateDocument(reservation);
213	    }
214	
215	    private Document generateDocument(Reservation reservation) {
216	        Room room = roomRepository.findByNumber(reservation.roomNumber()).orElseThrow();
217	        return documentService.generateDocument(reservation, room.type());
218	    }
219	
220	    private void sendConfirmationEmail(Reservation reservation) {
221	        Document document = generateDocument(reservation);
222	
223	        String body = "Olá, " + reservation.guestName() + "!\n\n" +
224	                     "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
225	                     document.text() + "\n\n" +
226	                     "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
227	                     "Até breve!";
228	
229	        Message message = new Message("EMAIL", reservation.guestEmail(),
230	            "Reserva confirmada - Pousada Maré Alta", body);
231	        messageRepository.save(message);
232	    }
