293	package com.pousadamarealta.domain;
294	
295	import java.math.BigDecimal;
296	import java.math.RoundingMode;
297	import java.time.LocalDate;
298	import java.time.temporal.ChronoUnit;
299	
300	public final class Reservation {
301	    private final long id;
302	    private final int roomNumber;
303	    private final String guestName;
304	    private final String guestEmail;
305	    private final GuestIdentification guestIdentification;
306	    private final LocalDate checkIn;
307	    private final LocalDate checkOut;
308	    private final int guests;
309	    private final RatePlan ratePlan;
310	    private final int nights;
311	    private final BigDecimal subtotal;
312	    private final BigDecimal discount;
313	    private final BigDecimal total;
314	    private ReservationStatus status;
315	    private BigDecimal amountPaid;
316	    private BigDecimal refund;
317	
318	    public Reservation(long id, int roomNumber, String guestName, String guestEmail,
319	                      GuestIdentification guestIdentification, LocalDate checkIn, LocalDate checkOut,
320	                      int guests, RatePlan ratePlan, BigDecimal nightlyRate) {
321	        this.id = id;
322	        this.roomNumber = roomNumber;
323	        this.guestName = guestName;
324	        this.guestEmail = guestEmail;
325	        this.guestIdentification = guestIdentification;
326	        this.checkIn = checkIn;
327	        this.checkOut = checkOut;
328	        this.guests = guests;
329	        this.ratePlan = ratePlan;
330	        this.nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
331	        this.subtotal = calculateSubtotal(nightlyRate);
332	        this.discount = calculateDiscount(this.subtotal);
333	        this.total = this.subtotal.subtract(this.discount);
334	        this.status = ReservationStatus.PENDING;
335	        this.amountPaid = BigDecimal.ZERO;
336	        this.refund = null;
337	    }
338	
339	    public Reservation(long id, int roomNumber, String guestName, String guestEmail,
340	                      GuestIdentification guestIdentification, LocalDate checkIn, LocalDate checkOut,
341	                      int guests, RatePlan ratePlan, int nights, BigDecimal subtotal,
342	                      BigDecimal discount, BigDecimal total, ReservationStatus status,
343	                      BigDecimal amountPaid, BigDecimal refund) {
344	        this.id = id;
345	        this.roomNumber = roomNumber;
346	        this.guestName = guestName;
347	        this.guestEmail = guestEmail;
348	        this.guestIdentification = guestIdentification;
349	        this.checkIn = checkIn;
350	        this.checkOut = checkOut;
351	        this.guests = guests;
352	        this.ratePlan = ratePlan;
353	        this.nights = nights;
354	        this.subtotal = subtotal;
355	        this.discount = discount;
356	        this.total = total;
357	        this.status = status;
358	        this.amountPaid = amountPaid;
359	        this.refund = refund;
360	    }
361	
362	    private BigDecimal calculateSubtotal(BigDecimal nightlyRate) {
363	        BigDecimal sum = BigDecimal.ZERO;
364	        LocalDate current = checkIn;
365	        while (current.isBefore(checkOut)) {
366	            BigDecimal rate = nightlyRate;
367	            if (isHighSeason(current)) {
368	                rate = rate.multiply(new BigDecimal("1.20"))
369	                          .setScale(2, RoundingMode.HALF_EVEN);
370	            }
371	            sum = sum.add(rate);
372	            current = current.plusDays(1);
373	        }
374	        return sum.setScale(2, RoundingMode.HALF_EVEN);
375	    }
376	
377	    private boolean isHighSeason(LocalDate date) {
378	        int month = date.getMonthValue();
379	        int day = date.getDayOfMonth();
380	
381	        if (month == 12 && day >= 15) return true;
382	        if (month == 1 || month == 2) return true;
383	        if (month == 7) return true;
384	
385	        return false;
386	    }
387	
388	    private BigDecimal calculateDiscount(BigDecimal subtotal) {
389	        if (ratePlan.discountRate().compareTo(BigDecimal.ZERO) == 0) {
390	            return BigDecimal.ZERO;
391	        }
392	        return subtotal.multiply(ratePlan.discountRate())
393	                      .setScale(2, RoundingMode.HALF_EVEN);
394	    }
395	
396	    public void confirm() {
397	        if (status != ReservationStatus.PENDING) {
398	            throw new IllegalStateException("Only pending reservations can be confirmed");
399	        }
400	        this.status = ReservationStatus.CONFIRMED;
401	        this.amountPaid = this.total;
402	    }
403	
404	    public void cancel() {
405	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
406	            throw new IllegalStateException("Only pending or confirmed reservations can be cancelled");
407	        }
408	        this.status = ReservationStatus.CANCELLED;
409	
410	        if (ratePlan == RatePlan.STANDARD && amountPaid.compareTo(BigDecimal.ZERO) > 0) {
411	            this.refund = amountPaid;
412	        } else {
413	            this.refund = BigDecimal.ZERO;
414	        }
