 24	    public String generateOccupancyReport(LocalDate date) {
 25	        List<Room> allRooms = roomRepository.findAll();
 26	        StringBuilder csv = new StringBuilder();
 27	        csv.append("room,type,reservation,check_in,check_out\n");
 28	
 29	        int occupiedCount = 0;
 30	
 31	        for (Room room : allRooms) {
 32	            List<Reservation> reservations = reservationRepository.findByRoomAndDateRange(
 33	                room.number(), date, date.plusDays(1));
 34	
 35	            Reservation occupying = reservations.stream()
 36	                .filter(r -> r.status() == ReservationStatus.CONFIRMED ||
 37	                           r.status() == ReservationStatus.CHECKED_IN ||
 38	                           r.status() == ReservationStatus.CHECKED_OUT)
 39	                .filter(r -> !r.checkIn().isAfter(date) && r.checkOut().isAfter(date))
 40	                .findFirst()
 41	                .orElse(null);
 42	
 43	            if (occupying != null) {
 44	                csv.append(room.number()).append(",")
 45	                   .append(room.type()).append(",")
 46	                   .append(occupying.id()).append(",")
 47	                   .append(occupying.checkIn().format(DATE_FORMATTER)).append(",")
 48	                   .append(occupying.checkOut().format(DATE_FORMATTER)).append("\n");
 49	                occupiedCount++;
