119	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
120	                                        GuestIdentification guestIdentification, LocalDate checkIn,
121	                                        LocalDate checkOut, int guests, RatePlan ratePlan) {
122	        Room room = roomRepository.findByNumber(roomNumber)
123	            .orElseThrow(() -> new RoomNotFoundException());
124	
125	        if (guests > room.capacity()) {
126	            throw new CapacityExceededException();
127	        }
128	
129	        if (guests < 1) {
130	            throw new InvalidRequestException("At least one guest is required");
131	        }
132	
133	        if (!checkOut.isAfter(checkIn)) {
134	            throw new InvalidRequestException("Check-out must be after check-in");
135	        }
136	
137	        List<Reservation> conflicts = reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
138	        if (!conflicts.isEmpty()) {
139	            throw new RoomUnavailableException();
140	        }
141	
142	        Reservation reservation = new Reservation(0, roomNumber, guestName, guestEmail,
143	            guestIdentification, checkIn, checkOut, guests, ratePlan, room.nightlyRate());
144	
145	        return reservationRepository.save(reservation);
