  2	
  3	import com.pousadamarealta.domain.Message;
  4	import javax.sql.DataSource;
  5	import java.sql.*;
  6	import java.util.ArrayList;
  7	import java.util.List;
  8	
  9	public final class MessageRepository {
 10	    private final DataSource dataSource;
 11	
 12	    public MessageRepository(DataSource dataSource) {
 13	        this.dataSource = dataSource;
 14	    }
 15	
 16	    public void initialize() {
 17	        try (Connection conn = dataSource.getConnection()) {
 18	            conn.createStatement().execute(
 19	                "CREATE TABLE IF NOT EXISTS messages (" +
 20	                "id SERIAL PRIMARY KEY, " +
 21	                "channel VARCHAR(20) NOT NULL, " +
 22	                "recipient VARCHAR(255) NOT NULL, " +
 23	                "subject TEXT NOT NULL, " +
 24	                "body TEXT NOT NULL)"
 25	            );
 26	        } catch (SQLException e) {
 27	            throw new RuntimeException("Failed to initialize messages table", e);
 28	        }
 29	    }
 30	
 31	    public Message save(Message message) {
 32	        String sql = "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?)";
 33	
 34	        try (Connection conn = dataSource.getConnection();
 35	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
 36	            stmt.setString(1, message.channel());
 37	            stmt.setString(2, message.to());
 38	            stmt.setString(3, message.subject());
 39	            stmt.setString(4, message.body());
 40	            stmt.executeUpdate();
 41	
 42	            try (ResultSet keys = stmt.getGeneratedKeys()) {
 43	                if (keys.next()) {
 44	                    return message.withId(keys.getLong(1));
 45	                }
 46	                throw new SQLException("Failed to get generated ID");
 47	            }
 48	        } catch (SQLException e) {
 49	            throw new RuntimeException("Failed to save message", e);
 50	        }
 51	    }
 52	
 53	    public List<Message> findAll() {
 54	        try (Connection conn = dataSource.getConnection();
 55	             PreparedStatement stmt = conn.prepareStatement("SELECT * FROM messages ORDER BY id");
 56	             ResultSet rs = stmt.executeQuery()) {
