260	            stmt.setInt(1, year);
261	            stmt.setInt(2, month);
262	
263	            try (ResultSet rs = stmt.executeQuery()) {
264	                List<Reservation> reservations = new ArrayList<>();
265	                while (rs.next()) {
266	                    reservations.add(mapReservation(rs));
267	                }
268	                return reservations;
269	            }
270	        } catch (SQLException e) {
271	            throw new RuntimeException("Failed to find reservations by month", e);
272	        }
273	    }
274	
275	    private Reservation mapReservation(ResultSet rs) throws SQLException {
276	        GuestIdentification guestId;
277	        String cpf = rs.getString("guest_cpf");
278	        String passport = rs.getString("guest_passport");
279	        String cnpj = rs.getString("company_cnpj");
280	
281	        if (cpf != null) {
282	            guestId = new GuestIdentification.IndividualGuest(cpf);
283	        } else if (passport != null) {
284	            guestId = new GuestIdentification.ForeignGuest(
285	                passport, rs.getString("guest_country"));
286	        } else {
287	            guestId = new GuestIdentification.CorporateGuest(
288	                cnpj, rs.getString("company_name"));
289	        }
290	
291	        return new Reservation(
292	            rs.getLong("id"),
293	            rs.getInt("room_number"),
294	            rs.getString("guest_name"),
295	            rs.getString("guest_email"),
296	            guestId,
297	            rs.getDate("check_in").toLocalDate(),
298	            rs.getDate("check_out").toLocalDate(),
299	            rs.getInt("guests"),
300	            RatePlan.valueOf(rs.getString("rate_plan")),
301	            rs.getInt("nights"),
302	            rs.getBigDecimal("subtotal"),
303	            rs.getBigDecimal("discount"),
304	            rs.getBigDecimal("total"),
305	            ReservationStatus.valueOf(rs.getString("status")),
306	            rs.getBigDecimal("amount_paid"),
307	            rs.getBigDecimal("refund")
308	        );
309	    }
310	}
311	package com.pousadamarealta.repository;
312	
313	import com.pousadamarealta.domain.Room;
314	import com.pousadamarealta.domain.RoomType;
315	import javax.sql.DataSource;
316	import java.sql.Connection;
317	import java.sql.PreparedStatement;
318	import java.sql.ResultSet;
319	import java.sql.SQLException;
320	import java.util.ArrayList;
321	import java.util.List;
322	import java.util.Optional;
323	
324	public final class RoomRepository {
325	    private final DataSource dataSource;
326	
327	    public RoomRepository(DataSource dataSource) {
328	        this.dataSource = dataSource;
329	    }
330	
331	    public void initialize() {
332	        try (Connection conn = dataSource.getConnection()) {
333	            conn.createStatement().execute(
334	                "CREATE TABLE IF NOT EXISTS rooms (" +
335	                "number INTEGER PRIMARY KEY, " +
336	                "type VARCHAR(20) NOT NULL)"
337	            );
338	
339	            if (count() == 0) {
340	                insertRoom(new Room(101, RoomType.STANDARD));
341	                insertRoom(new Room(102, RoomType.STANDARD));
342	                insertRoom(new Room(201, RoomType.DELUXE));
343	                insertRoom(new Room(202, RoomType.DELUXE));
344	                insertRoom(new Room(301, RoomType.SUITE));
345	            }
346	        } catch (SQLException e) {
347	            throw new RuntimeException("Failed to initialize rooms table", e);
348	        }
349	    }
350	
351	    private int count() throws SQLException {
352	        try (Connection conn = dataSource.getConnection();
353	             ResultSet rs = conn.createStatement().executeQuery("SELECT COUNT(*) FROM rooms")) {
354	            rs.next();
355	            return rs.getInt(1);
356	        }
357	    }
358	
359	    private void insertRoom(Room room) throws SQLException {
360	        try (Connection conn = dataSource.getConnection();
361	             PreparedStatement stmt = conn.prepareStatement(
362	                 "INSERT INTO rooms (number, type) VALUES (?, ?)")) {
363	            stmt.setInt(1, room.number());
364	            stmt.setString(2, room.type().name());
365	            stmt.executeUpdate();
366	        }
367	    }
368	
369	    public List<Room> findAll() {
370	        try (Connection conn = dataSource.getConnection();
371	             PreparedStatement stmt = conn.prepareStatement("SELECT number, type FROM rooms ORDER BY number");
372	             ResultSet rs = stmt.executeQuery()) {
373	
374	            List<Room> rooms = new ArrayList<>();
375	            while (rs.next()) {
376	                rooms.add(new Room(
377	                    rs.getInt("number"),
378	                    RoomType.valueOf(rs.getString("type"))
379	                ));
380	            }
381	            return rooms;
382	        } catch (SQLException e) {
383	            throw new RuntimeException("Failed to find rooms", e);
384	        }
385	    }
386	
387	    public Optional<Room> findByNumber(int number) {
388	        try (Connection conn = dataSource.getConnection();
389	             PreparedStatement stmt = conn.prepareStatement("SELECT number, type FROM rooms WHERE number = ?")) {
390	            stmt.setInt(1, number);
391	            try (ResultSet rs = stmt.executeQuery()) {
392	                if (rs.next()) {
393	                    return Optional.of(new Room(
394	                        rs.getInt("number"),
395	                        RoomType.valueOf(rs.getString("type"))
396	                    ));
397	                }
398	                return Optional.empty();
399	            }
400	        } catch (SQLException e) {
401	            throw new RuntimeException("Failed to find room", e);
402	        }
403	    }
404	}

